using System;using System.Drawing;using System.Drawing.Imaging;
class PreparePanelSprite{static void Main(string[] a){using(var src=new Bitmap(a[0])){int l=src.Width,t=src.Height,r=0,b=0;for(int y=0;y<src.Height;y++)for(int x=0;x<src.Width;x++)if(src.GetPixel(x,y).A>127){l=Math.Min(l,x);t=Math.Min(t,y);r=Math.Max(r,x);b=Math.Max(b,y);}int h=48,w=(int)Math.Round((r-l+1)*h/(double)(b-t+1));Color[] palette={Color.FromArgb(159,101,9),Color.FromArgb(216,142,12),Color.FromArgb(231,168,42)};using(var dst=new Bitmap(w,h,PixelFormat.Format32bppArgb)){for(int y=0;y<h;y++)for(int x=0;x<w;x++){var c=src.GetPixel(l+(int)((x+.5)*(r-l+1)/w),t+(int)((y+.5)*(b-t+1)/h));if(c.A<128){dst.SetPixel(x,y,Color.Transparent);continue;}int best=0,d=int.MaxValue;for(int k=0;k<palette.Length;k++){var p=palette[k];int next=(p.R-c.R)*(p.R-c.R)+(p.G-c.G)*(p.G-c.G)+(p.B-c.B)*(p.B-c.B);if(next<d){best=k;d=next;}}dst.SetPixel(x,y,palette[best]);}dst.Save(a[1]);Console.WriteLine(w+"x"+h+"; 3 amber colors + transparency");using(var preview=new Bitmap(160,220)){using(var g=Graphics.FromImage(preview)){g.Clear(Color.FromArgb(43,26,11));g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;g.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;g.DrawImage(dst,(160-w*4)/2,(220-h*4)/2,w*4,h*4);}preview.Save(a[2]);}}}}}
